add('20_003',4.5,'16:9，青正面头肩与上臂的中近景居画面中央，一手贴太阳穴，长马尾从右上垂入，衣服破边在下缘；摄影机缓慢后退半步接她走近，落幅头、按头手与微颤肩线同框。','青继续走近一小步，抬手按住太阳穴，单眼闭紧、另一眼半垂，嘴角勉强挑起；她先喘一口，再把嘲讽说向伏地武士。说到句尾，手指无意识地收紧，肩膀短短颤一下，脸上笑意却仍撑着；已有擦痕沿手臂保留，破边衣料随未平的呼吸轻抖，长发在肩后慢慢落稳。','青轮廓之外是米灰烟雾逐渐散开的软层，头侧上缘蓝灰云层透出，平台与武士留在画外低处。','上方冷白云光柔和覆盖脸与手背，烟层使后方偏亮，闭眼一侧压出浅冷灰影。','压着的一次喘息，指腹擦过发根，慢步鞋声落定后只留衣料轻颤。',ja=['大したことないんだね。'],tone='青喘过一口后勉强轻笑着嘲讽，句尾还在撑住气势，疲惫从余气里漏出。',kind='mixed',phase='reaction',node={'叙事阶段':'青按头喘息，微颤着嘲讽，本批结束','青.状态':'强化后负荷显出，仍站立可说话'},meaning='青按太阳穴、单眼闭、另一眼半垂、勉强笑与微颤保留；页外评论不入对白。',motion='青从远处走来后近处再落一步，镜头稍退保持尺度；没有从武士背上跳下。',ground='青站在平台石面，与伏地武士分开。',characters=['青'],card={'opening':'击倒对手后仍想把气势维持到最后。','beats':['抬手按头、单眼闭紧，先喘气','勉强挑嘴角说完嘲讽','手指收紧、肩短颤，笑意仍撑住'],'coupling':'表面的回敬与身体透出的负荷并行，最后一口气不够从容。','landing':'青仍站着，但已开始显出后续失力前兆。'})
